+
+def test_repr_list_of_lists() -> None:
+    """Test repr of List containing Lists."""
+    inner = tvm_ffi.List([1, 2])
+    outer = tvm_ffi.List([inner, tvm_ffi.List([3])])
+    assert ReprPrint(outer) == "[[1, 2], [3]]"
+
+
+# ---------- Nested dataclasses ----------
+
+
+def test_repr_nested_dataclass() -> None:
